{
  "name": "@usepipa/pipa",
  "version": "0.6.1",
  "description": "Run Pipa through Slack Socket Mode with OpenCode",
  "keywords": [
    "slack",
    "opencode",
    "ai-agent",
    "cli"
  ],
  "type": "module",
  "bin": {
    "pipa": "bin/pipa.mjs"
  },
  "files": [
    "bin",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test",
    "test:pack": "node scripts/pack-smoke.mjs",
    "test:engines": "node scripts/test-opencode-matrix.mjs",
    "test:beta": "node scripts/test-opencode-matrix.mjs --smoke",
    "test:slack:routines": "node scripts/slack-routine-eval.mjs",
    "test:slack:release": "node scripts/slack-release-eval.mjs"
  },
  "engines": {
    "node": ">=22"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lunchpaillola/pipa.git"
  },
  "homepage": "https://github.com/lunchpaillola/pipa#readme",
  "bugs": {
    "url": "https://github.com/lunchpaillola/pipa/issues"
  },
  "author": "Lunch Pail Labs",
  "license": "Apache-2.0",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@chat-adapter/slack": "4.38.1",
    "@chat-adapter/state-memory": "4.38.1",
    "@opencode/client": "2.0.29",
    "chat": "4.38.1",
    "cross-spawn": "7.0.6",
    "luxon": "3.7.2"
  }
}
